<?php declare(strict_types=1);require_once __DIR__.'/../../../bootstrap/app.php';use App\Services\Auth;use App\Services\AssignmentService;Auth::requirePermission('ASSIGNMENT_VIEW_OWN');$rows=AssignmentService::own();$pageTitle='My Assignments';require BASE_PATH.'/app/Views/layout/header.php';?><div class="page-head"><div><h1>My assignments</h1><p>Operations-confirmed transport assignments awaiting Phase 8 dispatch.</p></div><span class="badge"><?=h(count($rows))?></span></div><div class="card table-wrap"><table><thead><tr><th>Assignment</th><th>Load</th><th>Route</th><th>Truck / Driver</th><th>Accepted TZS</th><th>Status</th><th>Assigned UTC</th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><?=h($r['assignment_ref'])?></td><td><?=h($r['load_ref'])?></td><td><?=h($r['origin_city'].' → '.$r['destination_city'])?></td><td><?=h($r['registration_number'].' · '.$r['driver_name'])?></td><td><?=h(number_format((float)$r['offered_amount_tzs'],2))?></td><td><span class="status-pill status-<?=h($r['assignment_status'])?>"><?=h(str_replace('_',' ',$r['assignment_status']))?></span></td><td><?=h($r['assigned_at'])?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="7" class="muted">No assignments.</td></tr><?php endif;?></tbody></table></div><?php require BASE_PATH.'/app/Views/layout/footer.php';
